#!/usr/bin/env bash
# Build the release launcher `Project Helghast.exe` from installer/launcher/launcher.c with the MinGW-w64 gcc of the
# .#win shell (release pass 4). Run it through the sandbox:
#   nix develop .#win --command tools/sandbox.sh -- tools/release/build_launcher.sh [OUTDIR] [--smoke] [--icons DIR]
# OUTDIR defaults to build/launcher. Deterministic: -Os -s, no PE timestamp. ~20 KB, GUI subsystem, Unicode entry.
# Pass 6: launcher.rc (icon + version strings) compiled with windres; the icon comes from --icons DIR (default
# installer/art, generated by tools/release/installer_art.py). Without kz3-launcher.ico there it builds without
# resources and says so (the release build must have it: assemble the payload only after installer_art.py).
# --smoke also lays out OUTDIR/smoke/ (the launcher, a stand-in pythonw.exe from smoke_fakepy.c, an empty launch.py)
# for the Proton smoke test (tools/proton-test.sh on OUTDIR/smoke/"Project Helghast.exe"); the stand-in never ships.
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
OUT="$ROOT/build/launcher"; SMOKE=0; ICONS="$ROOT/installer/art"
while (( $# )); do
  case "$1" in
    --smoke) SMOKE=1 ;;
    --icons) ICONS="$2"; shift ;;
    *) OUT="$1" ;;
  esac
  shift
done
CC="${CC:-x86_64-w64-mingw32-gcc}"
WINDRES="${WINDRES:-x86_64-w64-mingw32-windres}"
# shellcheck disable=SC2054  # the comma belongs to the -Wl option
FLAGS=(-Os -s -municode -mwindows -Wall -Wextra -Werror -Wl,--no-insert-timestamp)
mkdir -p "$OUT"
RES=()
if [[ -f "$ICONS/kz3-launcher.ico" ]]; then
  "$WINDRES" --include-dir "$ICONS" -O coff -o "$OUT/launcher.res.o" "$ROOT/installer/launcher/launcher.rc"
  RES=("$OUT/launcher.res.o")
else
  echo "build_launcher: no $ICONS/kz3-launcher.ico: built WITHOUT icon and version resources (run installer_art.py)" >&2
fi
"$CC" "${FLAGS[@]}" -o "$OUT/Project Helghast.exe" "$ROOT/installer/launcher/launcher.c" "${RES[@]}"
stat -c "%s %n" "$OUT/Project Helghast.exe"
sha256sum "$OUT/Project Helghast.exe" | cut -c1-64
if (( SMOKE )); then
  S="$OUT/smoke"
  rm -rf "$S"; mkdir -p "$S/toolchain/python" "$S/kz3-setup/release"
  cp "$OUT/Project Helghast.exe" "$S/"
  "$CC" "${FLAGS[@]}" -o "$S/toolchain/python/pythonw.exe" "$ROOT/installer/launcher/smoke_fakepy.c"
  : > "$S/kz3-setup/release/launch.py"
  echo "smoke tree: $S"
fi
